#!/usr/bin/env python3
# P3-M9 (tier1c): generate synth_path.go (`path`) from gc 1.27.1's path.
# See header for deviations.
import os
import re
import subprocess

# --- P1-R1-2 portability prologue: GOROOT and OUTDIR are environment-driven
# so the generator is CI-runnable and never writes outside the repo.
#   GRAALGO_GOROOT   Go installation whose gc 1.27.1 sources are read
#                    (default: `go env GOROOT`).
#   GEN_SYNTH_OUTDIR directory for the generated file(s) (default: this
#                    script's directory, i.e. in-place regeneration).
_HERE = os.path.dirname(os.path.abspath(__file__))

def _graalgo_goroot():
    g = os.environ.get("GRAALGO_GOROOT")
    if g:
        return g
    try:
        return subprocess.run(["go", "env", "GOROOT"], capture_output=True,
                              text=True, check=True).stdout.strip()
    except Exception as e:
        raise SystemExit(
            "gen_synth: cannot determine GOROOT; set GRAALGO_GOROOT (%s)" % e)

OUTDIR = os.environ.get("GEN_SYNTH_OUTDIR", _HERE)

GOROOT = os.path.join(_graalgo_goroot(), "src", "path")


HEADER = '''// P3-M9 (tier1c): synthetic `path` package.
//
// REAL Go source, embedded as text and type-checked on demand with the
// overlay importer (same mechanism as the P3-M7 synthetic math package,
// ADR-0007 D5).
//
// Value model:
//   - path.go is gc 1.27.1's implementation ported verbatim.
//   - DEVIATION 1 (documented): internal/bytealg is not in the frontend
//     overlay (tier1d, in progress). bytealg.LastIndexByteString(s, '/')
//     -> strings.LastIndexByte(s, '/'). Identical semantics.
//     Retest trigger: internal/bytealg lands in the overlay.
//   - DEVIATION 2 (documented): Split (2-result) via Appendix M
//     (__pathSplit helper + pathSplitPair + desugar entry).
//   - SCOPE-LIMITED (documented): Match, scanChunk, matchChunk, getEsc
//     (pattern matching) are DROPPED. They involve 3-result functions
//     and utf8.DecodeRuneInString; the full port awaits unicode/utf8
//     in the overlay. Retest trigger: unicode/utf8 lands (tier1a).
//     ErrBadPattern IS ported (from match.go): it is a dependency-free
//     exported var (errors.New only) that consumers of the pattern API
//     reference directly (e.g. io/fs's Glob reports path.ErrBadPattern;
//     PKG-029: the synthetic package must expose it or every such
//     reference fails type-checking with "undefined: path.ErrBadPattern").
//
// Generated by gen_synth_path.py from gc 1.27.1; DO NOT EDIT BY
// HAND (edit the generator and re-run).
package main

// syntheticPathSource is the P3-M9 synthetic `path` package.
const syntheticPathSource = `package path

import (
	"errors"
	"strings"
)

// ---- Deviation 2: Appendix M for Split ----
type pathSplitPair struct {
	dir  string
	file string
}

func __pathSplit(path string) pathSplitPair {
	i := strings.LastIndexByte(path, '/')
	return pathSplitPair{dir: path[:i+1], file: path[i+1:]}
}

'''

def strip_imports(src):
    src = re.sub(r'^import \(\n(?:.*\n)*?^\)\n', '', src, count=1, flags=re.M)
    src = re.sub(r'^import "[^"]*"\n', '', src, flags=re.M)
    return src

def strip_package(src):
    return re.sub(r"^package path\n", "", src, count=1, flags=re.M)


def convert_raw_strings(src):
    """Convert Go raw strings to interpreted strings.

    P1-09: the frontend no longer repairs backtick-stripping damage at
    load, so the generator must emit parseable Go itself. Copied from
    gen_synth_archive_mime.py: raw strings become interpreted strings
    (escapes rewritten), '`' rune literals become '\\x60', comment
    backticks become "'". A naive src.replace("`", "'") would turn a
    multi-char raw string into an illegal rune literal and a 1-char raw
    string into a rune, silently changing its type.
    """
    out = []
    i, n = 0, len(src)
    while i < n:
        if src.startswith('//', i):
            j = src.find('\n', i)
            if j == -1: j = n
            out.append(src[i:j].replace('`', "'"))
            i = j
            continue
        if src.startswith('/*', i):
            j = src.find('*/', i)
            j = n if j == -1 else j + 2
            out.append(src[i:j].replace('`', "'"))
            i = j
            continue
        if src[i] == '"' or src[i] == "'":
            q = src[i]
            if q == "'" and src.startswith("'`'", i):
                out.append("'\\x60'")
                i += 3
                continue
            j = i + 1
            while j < n:
                if src[j] == '\\':
                    j += 2
                    continue
                if src[j] == q:
                    j += 1
                    break
                j += 1
            out.append(src[i:j])
            i = j
            continue
        if src[i] == '`':
            j = src.find('`', i+1)
            if j == -1:
                out.append("'")
                i += 1
                continue
            content = src[i+1:j]
            esc = []
            for ch in content:
                if ch == '\\': esc.append('\\\\')
                elif ch == '"': esc.append('\\"')
                elif ch == '\n': esc.append('\\n')
                elif ch == '\r': esc.append('\\r')
                elif ch == '\t': esc.append('\\t')
                elif ord(ch) < 0x20 or ord(ch) == 0x7f:
                    esc.append('\\x%02x' % ord(ch))
                else: esc.append(ch)
            out.append('"' + ''.join(esc) + '"')
            i = j + 1
            continue
        out.append(src[i])
        i += 1
    return ''.join(out)

def main():
    parts = [HEADER]
    # ErrBadPattern (from match.go): match.go is otherwise scope-limited
    # (Match/scanChunk/matchChunk/getEsc dropped — see header), but
    # ErrBadPattern is a dependency-free exported var (errors.New only)
    # that consumers of the pattern API reference directly (e.g. io/fs's
    # Glob reports path.ErrBadPattern). A synthetic package must expose
    # every referenced exported declaration, so it is ported verbatim;
    # extracted mechanically so upstream wording changes flow through.
    # PKG-029: without it, any path.ErrBadPattern reference fails
    # type-checking with "undefined: path.ErrBadPattern".
    with open(f"{GOROOT}/match.go") as f:
        msrc = f.read()
    m = re.search(r"(?m)^// ErrBadPattern indicates.*\nvar ErrBadPattern = .*\n", msrc)
    assert m, "ErrBadPattern declaration not found in match.go"
    # Same backtick conversion as path.go below: the declaration is
    # embedded in a raw-string const.
    decl = convert_raw_strings(m.group(0))
    parts.append("// ---- ErrBadPattern, ported from match.go ----\n" + decl + "\n")
    # Only path.go (match.go is otherwise scope-limited).
    with open(f"{GOROOT}/path.go") as f:
        src = f.read()
    src = strip_package(src)
    src = strip_imports(src)
    src = src.replace("bytealg.LastIndexByteString", "strings.LastIndexByte")
    src = convert_raw_strings(src)
    # Replace Split with a fail-fast stub (exact gc signature for
    # type-checking; 2-target call sites desugar to __pathSplit via the
    # Appendix-M table in mrdesugar_m5.go; every other position fails fast).
    # The stub is emitted immediately before Dir's doc comment (not in gc's
    # Split position between Clean and Join).
    SPLIT_STUB = (
        "// Split splits path immediately following the final slash, separating it\n"
        "// into a directory and file name component. If there is no slash in path,\n"
        "// Split returns an empty dir and file set to path.\n"
        "// The returned values have the property that path = dir+file.\n"
        "//\n"
        "// (Appendix M: 2-target call sites desugar to __pathSplit; every other\n"
        "// position fails fast. Body never runs.)\n"
        "func Split(path string) (dir, file string) {\n"
        "\tpanic(\"path: Split: not in M9 scope (multi-result calls need the M9 desugar; re-test when WS D lands)\")\n"
        "}\n"
    )
    src = re.sub(r"^func Split\(.*?^}\n", "", src, count=1, flags=re.M | re.S)
    # Rewrite Dir's internal Split call.
    src = src.replace(
        "\tdir, _ := Split(path)\n\treturn Clean(dir)",
        "\t// P3-M9: Split -> __pathSplit (no multi-result calls in synthetic).\n\treturn Clean(__pathSplit(path).dir)",
    )
    parts.append(src.rstrip() + "\n\n")
    out = "".join(parts)
    # The Split stub sits immediately before Dir's doc comment (not in gc's
    # Split position between Clean and Join).
    anchor = "// After dropping the final element using [Split],"
    assert out.count(anchor) == 1, "Dir doc anchor not found exactly once"
    out = out.replace(anchor, SPLIT_STUB + "\n" + anchor)
    out = out.rstrip() + "\n`\n"
    with open(os.path.join(OUTDIR, "synth_path.go"), "w") as f:
        f.write(out)
    print("wrote synth_path.go", len(out), "bytes")

main()
